// ---- DataTransfer entry / directory drop helpers ----
function collectFileEntriesFromEntry(entry, pathPrefix, out) {
  return new Promise((resolve, reject) => {
    if (!entry) return resolve(out);
    if (entry.isFile) {
      entry.file((file) => {
        const rel = (pathPrefix ? pathPrefix + '/' : '') + file.name;
        try { Object.defineProperty(file, 'webkitRelativePath', { configurable: true, value: rel }); } catch {}
        file._sshtermRelPath = rel;
        out.push(file);
        resolve(out);
      }, reject);
      return;
    }
    if (entry.isDirectory) {
      const reader = entry.createReader();
      const prefix = (pathPrefix ? pathPrefix + '/' : '') + entry.name;
      const readBatch = () => {
        reader.readEntries(async (entries) => {
          if (!entries.length) return resolve(out);
          try {
            for (const child of entries) {
              await collectFileEntriesFromEntry(child, prefix, out);
            }
            readBatch();
          } catch (err) { reject(err); }
        }, reject);
      };
      readBatch();
      return;
    }
    resolve(out);
  });
}

async function collectDataTransferFiles(dataTransfer) {
  const out = [];
  const items = dataTransfer && dataTransfer.items ? [...dataTransfer.items] : [];
  if (items.length && items.some(it => typeof it.webkitGetAsEntry === 'function' && it.webkitGetAsEntry())) {
    for (const item of items) {
      if (item.kind && item.kind !== 'file') continue;
      const entry = item.webkitGetAsEntry ? item.webkitGetAsEntry() : null;
      if (entry) await collectFileEntriesFromEntry(entry, '', out);
    }
    return out;
  }
  return [...((dataTransfer && dataTransfer.files) || [])];
}

async function uploadDroppedFiles(tab, files) {
  if (!files.length) return;
  if (sftpPath === '.') {
    send({ type: 'sftp', id: tab.id, action: 'cwd' });
    await new Promise(r => setTimeout(r, 800));
  }
  const dir = sftpPath || '.';
  const hasRel = files.some(f => f._sshtermRelPath || f.webkitRelativePath);
  if (hasRel && files.length > 1) {
    const total = files.length;
    const totalBytes = files.reduce((sum, file) => sum + file.size, 0);
    const progressByFile = new Array(total).fill(0);
    const rootName = (files[0]._sshtermRelPath || files[0].webkitRelativePath || files[0].name).split('/')[0];
    const task = newTransferTask('上传目录', rootName);
    let ok = 0, fail = 0, nextFile = 0;
    const updateOverallProgress = (i, filePct, rel) => {
      progressByFile[i] = filePct;
      const transferred = progressByFile.reduce((sum, value, index) => sum + value * files[index].size, 0);
      const pct = totalBytes ? transferred / totalBytes * 100 : progressByFile.filter(value => value >= 1).length / total * 100;
      showProgress(`上传目录: ${rel} ${(filePct * 100).toFixed(0)}%（总计 ${pct.toFixed(0)}%）`, pct);
      updateTransferTask(task, pct);
    };
    const worker = async () => {
      while (nextFile < total) {
        await waitForUploadQueue();
        const i = nextFile++;
        const f = files[i];
        const rel = f._sshtermRelPath || f.webkitRelativePath || f.name;
        try {
          const result = await uploadFileSmart(tab.id, dir, rel, f, filePct => updateOverallProgress(i, filePct, rel));
          if (result.status === 200) { ok++; updateOverallProgress(i, 1, rel); } else fail++;
        } catch (err) { fail++; }
      }
    };
    await Promise.all(Array.from({ length: Math.min(3, total) }, worker));
    updateTransferTask(task, 100, fail ? 'failed' : 'done', `${ok}/${total} 成功${fail ? `，${fail} 失败` : ''}`);
    doneProgress(`✅ 文件夹上传完成: ${ok}/${total} 成功${fail ? `, ${fail} 失败` : ''}`);
    if (sftpOpen) sftpLoad();
    return;
  }
  for (const f of files) {
    const name = f._sshtermRelPath || f.webkitRelativePath || f.name;
    setStatus(`上传: ${name} (${fmtSize(f.size)})...`);
    try {
      const result = await uploadFileSmart(tab.id, dir, name, f, progress => {
        showProgress(`上传: ${name} ${(progress * 100).toFixed(0)}%`, progress * 100);
      });
      if (result.status !== 200) throw new Error(`服务端返回 ${result.status}`);
      setStatus(`✅ 已上传: ${name}`);
      doneProgress(`✅ 已上传: ${name}`);
      setTimeout(() => { if (sftpOpen) sftpLoad(); }, 500);
    } catch (err) { setStatus(`上传失败: ${name} — ${err.message}`); }
  }
}


let _dragCounter = 0;
$('terms').addEventListener('dragenter', (e) => {
  if (draggingSessionId) return;
  e.preventDefault();
  _dragCounter++;
  $('terms').classList.add('drag-over');
});
$('terms').addEventListener('dragleave', () => {
  _dragCounter--;
  if (_dragCounter <= 0) { _dragCounter = 0; $('terms').classList.remove('drag-over'); }
});
$('terms').addEventListener('dragover', (e) => {
  if (draggingSessionId) return;
  e.preventDefault();
});
$('terms').addEventListener('drop', async (e) => {
  if (draggingSessionId) return; // 会话列表拖拽排序
  e.preventDefault();
  _dragCounter = 0;
  $('terms').classList.remove('drag-over');
  const tab = tabs.find(t => t.id === activeTabId);
  if (!tab || tab.cfg.type !== 'ssh' || tab.state !== 'connected') return setStatus('拖拽上传仅支持 SSH 已连接时');
  let files = [];
  try {
    files = await collectDataTransferFiles(e.dataTransfer);
  } catch (err) {
    files = [...(e.dataTransfer.files || [])];
  }
  if (!files.length) return;
  await uploadDroppedFiles(tab, files);
});

// SFTP 面板同样支持拖放文件/文件夹上传
(function bindSftpPanelDrop() {
  const panel = $('sftp-panel');
  if (!panel || panel._sshtermDropBound) return;
  panel._sshtermDropBound = true;
  let counter = 0;
  panel.addEventListener('dragenter', (e) => {
    if (draggingSessionId) return;
    e.preventDefault();
    counter++;
    panel.classList.add('drag-over');
  });
  panel.addEventListener('dragleave', () => {
    counter--;
    if (counter <= 0) { counter = 0; panel.classList.remove('drag-over'); }
  });
  panel.addEventListener('dragover', (e) => {
    if (draggingSessionId) return;
    e.preventDefault();
  });
  panel.addEventListener('drop', async (e) => {
    if (draggingSessionId) return;
    e.preventDefault();
    e.stopPropagation();
    counter = 0;
    panel.classList.remove('drag-over');
    const tab = tabs.find(t => t.id === activeTabId);
    if (!tab || tab.cfg.type !== 'ssh' || tab.state !== 'connected') return setStatus('拖拽上传仅支持 SSH 已连接时');
    let files = [];
    try { files = await collectDataTransferFiles(e.dataTransfer); }
    catch (err) { files = [...(e.dataTransfer.files || [])]; }
    if (!files.length) return;
    await uploadDroppedFiles(tab, files);
  });
})();

